attempts.raw_output:
{
  "motion_reading":"Bỏ kỳ thi tốt nghiệp THPT quốc gia; việc xét tốt nghiệp dựa trên đánh giá quá trình của nhà trường, và các trường đại học tự lựa chọn phương thức tuyển sinh riêng.",
  "definitions":[
    {
      "term":"đánh giá quá trình",
      "meaning":"quá trình học tập và các tiêu chí học tập được nhà trường ghi nhận, tổng hợp trong suốt 3 năm trung học phổ thông"
    }
  ],
  "arguments":[
    {
      "id":"A1",
      "title":"Đảm bảo tiêu chuẩn công bằng và đồng nhất",
      "claim":"Duy trì kỳ thi tốt nghiệp THPT quốc gia là cần thiết để bảo đảm tiêu chuẩn công bằng và đồng nhất trong việc xác nhận tốt nghiệp.",
      "reasoning":"Một kỳ thi chung cung cấp thước đo chuẩn, giảm thiểu sự chênh lệch do khác biệt về nguồn lực, chất lượng giáo viên và môi trường học tập giữa các trường; vì vậy mọi học sinh đều được đánh giá trên cùng một tiêu chí khách quan.",
      "example":"Giả sử hai trường trung học, một trường ở khu vực thành thị có đầy đủ tài liệu, giáo viên chuyên môn cao, một trường ở vùng nông thôn thiếu giáo viên và tài liệu; nếu chỉ dựa vào đánh giá nội bộ, học sinh trường nông thôn sẽ khó chứng minh năng lực so với học sinh thành thị.",
      "impact":"Sự bất công trong việc công nhận tốt nghiệp sẽ gia tăng, gây mất niềm tin của xã hội vào bằng cấp và làm khó khăn cho các trường đại học trong việc lựa chọn sinh viên."
    },
    {
      "id":"A2",
      "title":"Gánh nặng cho nhà trường và đại học",
      "claim":"Bỏ kỳ thi sẽ tạo gánh nặng quá lớn cho nhà trường trong việc thực hiện đánh giá chi tiết và khiến các trường đại học khó lựa chọn tiêu chí tuyển sinh hợp lý.",
      "reasoning":"Việc đánh giá toàn diện mỗi học sinh đòi hỏi thời gian, nhân lực và công cụ chuyên môn mà nhiều trường trung học không có; đồng thời, các trường đại học sẽ phải thiết kế nhiều hình thức tuyển sinh khác nhau, làm tăng chi phí và độ phức tạp của quy trình tuyển sinh.",
      "example":"Giả sử một trường trung học có 500 học sinh, nhà trường phải chuẩn bị hồ sơ đánh giá chi tiết cho từng học sinh, bao gồm điểm học thuật, kỹ năng mềm, hoạt động ngoại khóa; công việc này vượt quá khả năng của đội ngũ giáo viên và gây trì hoãn quá trình tốt nghiệp.",
      "impact":"Chất lượng đánh giá sẽ giảm, chi phí giáo dục tăng, và quá trình tuyển sinh đại học trở nên chậm trễ và không đồng nhất, làm suy giảm hiệu quả của hệ thống giáo dục."
    }
  ],
  "anticipated_opponent_arguments":[
    {
      "id":"O1",
      "learner_claim":"Bỏ kỳ thi sẽ giảm áp lực học đường, giúp học sinh phát triển toàn diện và giảm tình trạng học sinh chỉ học để làm bài thi.",
      "planned_response":"Mặc dù giảm áp lực là mong muốn, nhưng không có cơ chế thay thế đủ để đảm bảo công bằng; áp lực sẽ chuyển sang đánh giá nội bộ, gây áp lực lên giáo viên và phụ huynh, đồng thời thiếu tiêu chuẩn chung làm giảm khả năng so sánh và lựa chọn đại học."
    },
    {
      "id":"O2",
      "learner_claim":"Đánh giá dựa trên quá trình học tập cho phép trường học cân nhắc năng lực thực tế và giảm sự phụ thuộc vào kiến thức nhớ vè.",
      "planned_response":"Quá trình đánh giá nội bộ dễ bị thiên vị, phụ thuộc vào quan điểm của giáo viên; các trường có nguồn lực tốt hơn sẽ dễ “đánh giá” học sinh tốt hơn, tạo bất bình và làm mất tính khách quan của bằng tốt nghiệp."
    }
  ],
  "weighing":"Khi cân nhắc tổng thể, việc duy trì kỳ thi tốt nghiệp THPT quốc gia vẫn là giải pháp công bằng, khả thi và ít tốn kém hơn so với việc giao toàn bộ trách nhiệm đánh giá cho các trường học không đồng đều; nó bảo đảm tiêu chuẩn đồng nhất, giảm gánh nặng cho nhà trường và giúp các trường đại học có tiêu chí tuyển sinh rõ ràng, do đó phe Phản đối thắng."
}
